	private static Stats read(Path path, boolean captureDisclosure) throws Exception {
		Stats stats = new Stats();
		MessageDigest digest = MessageDigest.getInstance("SHA-256");
		try (RecordingFile recording = new RecordingFile(path);
				DataOutputStream payload = new DataOutputStream(new BufferedOutputStream(
						new DigestOutputStream(OutputStream.nullOutputStream(), digest), 65536))) {
			while (recording.hasMoreEvents()) {
				RecordedEvent event = recording.readEvent();
				String type = event.getEventType().getName();
				String id = Long.toString(event.getEventType().getId());
				String old = stats.typeIds.putIfAbsent(id, type);
				if (old != null && !old.equals(type)) {
					throw new IllegalStateException("Event type identifier changed its meaning");
				}
				stats.counts.merge(type, 1L, Long::sum);
				if (!REMOVED.contains(type)) {
					text(payload, type);
					payload.writeLong(event.getStartTime().getEpochSecond());
					payload.writeInt(event.getStartTime().getNano());
					payload.writeLong(event.getEndTime().getEpochSecond());
					payload.writeInt(event.getEndTime().getNano());
					canonical(payload, event, 0);
				}
				if (captureDisclosure && REMOVED.contains(type)) {
					boolean process = type.equals("jdk.SystemProcess");
					String name = process ? "commandLine#" + stats.counts.get(type)
							: event.getString(event.hasField("key") ? "key" : "name");
					String value = event.getString(process ? "commandLine" : "value");
					boolean present = value != null && !value.isEmpty();
					boolean nameMatch = SENSITIVE_NAME.matcher(name).find();
					boolean booleanFeatureFlag = type.equals("jdk.InitialEnvironmentVariable")
							&& name.equals("ENABLE_BROWSER_CREDENTIAL_CAPABILITIES") && present
							&& BOOLEAN_FLAG_VALUES.contains(value.toLowerCase(Locale.ROOT));
					stats.names.add(fields("eventType", type, "name", name, "nonemptyValuePresent", present,
							"sensitiveNameMatched", nameMatch, "nonSecretBooleanFeatureFlag", booleanFeatureFlag,
							"classificationReason", booleanFeatureFlag ? "exact-feature-flag-key-and-boolean-like-value"
									: nameMatch ? "sensitive-name-candidate" : "name-does-not-match-sensitive-pattern"));
					if (!present) {
						continue;
					}
					if (nameMatch && !booleanFeatureFlag) {
						stats.probes.add(new Probe(type, name, "sensitive-name", value));
					}
					if (process) {
						Matcher arguments = COMMAND_OPTION.matcher(value);
						while (arguments.find()) {
							if (SENSITIVE_NAME.matcher(arguments.group(1)).find()) {
								Matcher optionValue = OPTION_VALUE.matcher(value).region(arguments.end(), value.length());
								if (optionValue.lookingAt()) {
									addArgument(stats, type, name, optionValue.group(1), "command-credential-argument");
								}
							}
						}
						Matcher assignments = BARE_ASSIGNMENT.matcher(value);
						while (assignments.find()) {
							if (SENSITIVE_NAME.matcher(assignments.group(1)).find()) {
								addArgument(stats, type, name, assignments.group(2), "command-credential-assignment");
							}
						}
					}
					Matcher assignments = SENSITIVE_ASSIGNMENT.matcher(value);
					while (assignments.find()) {
						stats.probes.add(new Probe(type, name, "credential-assignment", assignments.group(1)));
					}
					Matcher uris = URI_TOKEN.matcher(value);
					while (uris.find()) {
						try {
							URI uri = URI.create(uris.group());
							addUserInfo(stats, type, name, uri.getRawUserInfo(), "raw-uri-user-info");
							addUserInfo(stats, type, name, uri.getUserInfo(), "decoded-uri-user-info");
						} catch (IllegalArgumentException ignored) {
							// Not all environment values that contain :// are complete URI strings.
						}
					}
				}
			}
		}
		stats.retainedPayloadSha256 = HexFormat.of().formatHex(digest.digest());
		return stats;
	}

	private static void text(DataOutputStream output, String value) throws Exception {
		output.writeInt(value.length());
		for (int i = 0; i < value.length(); i++) {
			output.writeChar(value.charAt(i));
		}
	}

	private static void canonical(DataOutputStream output, Object value, int depth) throws Exception {
		if (depth > 64) {
			throw new IllegalStateException("Unexpected recursive event metadata");
		}
		if (value == null) {
			output.writeByte(0);
		} else if (value instanceof String string) {
			output.writeByte(1);
			text(output, string);
		} else if (value instanceof Boolean number) {
			output.writeByte(2);
			output.writeBoolean(number);
		} else if (value instanceof Byte number) {
			output.writeByte(3);
			output.writeByte(number);
		} else if (value instanceof Short number) {
			output.writeByte(4);
			output.writeShort(number);
		} else if (value instanceof Integer number) {
			output.writeByte(5);
			output.writeInt(number);
		} else if (value instanceof Long number) {
			output.writeByte(6);
			output.writeLong(number);
		} else if (value instanceof Float number) {
			output.writeByte(7);
			output.writeInt(Float.floatToRawIntBits(number));
		} else if (value instanceof Double number) {
			output.writeByte(8);
			output.writeLong(Double.doubleToRawLongBits(number));
		} else if (value instanceof Character character) {
			output.writeByte(9);
			output.writeChar(character);
		} else if (value instanceof RecordedObject object) {
			output.writeByte(10);
			text(output, object.getClass().getName());
			// These public identities are stored outside getFields() in the JDK consumer wrappers.
			if (object instanceof RecordedClass recorded) {
				output.writeByte(1);
				output.writeLong(recorded.getId());
			} else if (object instanceof RecordedClassLoader recorded) {
				output.writeByte(2);
				output.writeLong(recorded.getId());
			} else if (object instanceof RecordedThread recorded) {
				output.writeByte(3);
				output.writeLong(recorded.getId());
			} else if (object instanceof RecordedEvent recorded) {
				output.writeByte(4);
				output.writeLong(recorded.getEventType().getId());
			} else {
				output.writeByte(0);
			}
			List<ValueDescriptor> descriptors = object.getFields();
			output.writeInt(descriptors.size());
			for (ValueDescriptor descriptor : descriptors) {
				text(output, descriptor.getName());
				text(output, descriptor.getTypeName());
				output.writeBoolean(descriptor.isArray());
				canonical(output, object.getValue(descriptor.getName()), depth + 1);
			}
		} else if (value.getClass().isArray()) {
			output.writeByte(11);
			int length = Array.getLength(value);
			output.writeInt(length);
			for (int i = 0; i < length; i++) {
				canonical(output, Array.get(value, i), depth + 1);
			}
		} else {
			throw new IllegalStateException("Unsupported event field representation");
		}
	}

	private static void addArgument(Stats stats, String type, String name, String value, String reason) {
		if (value.length() >= 2 && (value.charAt(0) == '"' || value.charAt(0) == '\'')) {
			value = value.substring(1, value.length() - 1);
		}
		if (!value.isEmpty()) {
			stats.probes.add(new Probe(type, name, reason, value));
		}
	}

	private static void addUserInfo(Stats stats, String type, String name, String value, String reason) {
		if (value == null || value.isEmpty()) {
			return;
		}
		stats.probes.add(new Probe(type, name, reason, value));
		int colon = value.indexOf(':');
		if (colon >= 0 && colon + 1 < value.length()) {
			stats.probes.add(new Probe(type, name, reason + "-password", value.substring(colon + 1)));
		}
	}

	private static Map<String, byte[]> encodings(String value) {
		Map<String, byte[]> result = new LinkedHashMap<>();
		result.put("UTF-8", value.getBytes(StandardCharsets.UTF_8));
		if (StandardCharsets.ISO_8859_1.newEncoder().canEncode(value)) {
			result.put("ISO-8859-1", value.getBytes(StandardCharsets.ISO_8859_1));
		}
		result.put("UTF-16LE", value.getBytes(StandardCharsets.UTF_16LE));
		result.put("UTF-16BE", value.getBytes(StandardCharsets.UTF_16BE));
		ByteArrayOutputStream compressed = new ByteArrayOutputStream();
		for (int i = 0; i < value.length(); i++) {
			int character = value.charAt(i);
			while (character >= 128) {
				compressed.write((character & 127) | 128);
				character >>>= 7;
			}
			compressed.write(character);
		}
		result.put("JFR-compressed-UTF16", compressed.toByteArray());
		return result;
	}

	private static boolean contains(byte[] haystack, byte[] needle) {
		if (needle.length == 0) {
			throw new IllegalArgumentException("Empty disclosure search is not meaningful");
		}
		int[] skip = new int[256];
		Arrays.fill(skip, needle.length);
		for (int i = 0; i + 1 < needle.length; i++) {
			skip[needle[i] & 255] = needle.length - 1 - i;
		}
		for (int end = needle.length - 1; end < haystack.length;) {
			int i = needle.length - 1;
			while (i >= 0 && haystack[end - needle.length + 1 + i] == needle[i]) {
				i--;
			}
			if (i < 0) {
				return true;
			}
			end += skip[haystack[end] & 255];
		}
		return false;
	}

	private static Map<String, Object> fields(Object... pairs) {
		Map<String, Object> result = new LinkedHashMap<>();
		for (int i = 0; i < pairs.length; i += 2) {
			result.put((String) pairs[i], pairs[i + 1]);
		}
		return result;
	}

	private static String json(Object value) {
		if (value == null || value instanceof Number || value instanceof Boolean) {
			return String.valueOf(value);
		}
		if (value instanceof Map<?, ?> map) {
			List<String> entries = new ArrayList<>();
			for (Map.Entry<?, ?> entry : map.entrySet()) {
				entries.add(json(entry.getKey().toString()) + ":" + json(entry.getValue()));
			}
			return "{" + String.join(",", entries) + "}";
		}
		if (value instanceof Iterable<?> items) {
			List<String> entries = new ArrayList<>();
			for (Object item : items) {
				entries.add(json(item));
			}
			return "[" + String.join(",", entries) + "]";
		}
		StringBuilder output = new StringBuilder("\"");
		for (char c : value.toString().toCharArray()) {
			switch (c) {
			case '"' -> output.append("\\\"");
			case '\\' -> output.append("\\\\");
			case '\n' -> output.append("\\n");
			case '\r' -> output.append("\\r");
			case '\t' -> output.append("\\t");
			default -> {
				if (c < 32) {
					output.append(String.format("\\u%04x", (int) c));
				} else {
					output.append(c);
				}
			}
			}
		}
		return output.append('"').toString();
	}

	private record Probe(String type, String name, String reason, String value) {
	}

	private static final class Stats {
		private final Map<String, Long> counts = new TreeMap<>();
		private final Map<String, String> typeIds = new TreeMap<>();
		private final List<Map<String, Object>> names = new ArrayList<>();
		private final List<Probe> probes = new ArrayList<>();
		private String retainedPayloadSha256;
	}
